package com.course.platform.service.impl;

import com.course.platform.common.exception.BusinessException;
import com.course.platform.domain.entity.*;
import org.junit.jupiter.api.*;
import org.springframework.aop.framework.ProxyFactory;
import org.springframework.transaction.annotation.AnnotationTransactionAttributeSource;
import org.springframework.transaction.interceptor.TransactionInterceptor;
import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.*;

/** 旧入口修改追加兼容快照，保留原钱包、历史价格和未知资格，不把旧余额认领为新预存。 */
class CoursePrivateLegacySyncTransactionTest {
    CoursePrivateRenewalTransactionTest f;
    CoursePrivateLegacySyncService service;
    @BeforeEach void setup() throws Exception {f=new CoursePrivateRenewalTransactionTest();f.setup();f.f.f.f.jdbc.execute("CREATE UNIQUE INDEX legacy_plan_code ON course_private_plan(platform_id,plan_code)");f.f.f.f.jdbc.execute("CREATE UNIQUE INDEX legacy_version_number ON course_private_plan_version(plan_id,version_no)");f.f.f.f.jdbc.update("UPDATE course_private_contract SET operations_mode='LEGACY_PERMANENT'");f.f.f.f.jdbc.update("UPDATE course_private_contract_term SET operations_mode='LEGACY_PERMANENT',qualification_kind='LEGACY_UNKNOWN' WHERE id=?",f.sourceId);f.f.f.f.jdbc.update("UPDATE course_private_plan SET mode='LEGACY_PERMANENT',plan_code='__LEGACY_PERMANENT',status='DISABLED',visible_to_agents=FALSE");var target=new CoursePrivateLegacySyncService(f.f.f.f.users,f.f.f.f.contracts,f.f.f.f.wallets,f.f.f.plans,f.f.f.versions,f.f.f.terms,f.f.f.events,f.f.f.json,new CoursePrivateOperationsTime(f.f.f.clock));org.springframework.test.util.ReflectionTestUtils.setField(target,"enabled",true);var proxy=new ProxyFactory(target);proxy.addAdvice(new TransactionInterceptor(f.f.f.f.tx.getTransactionManager(),new AnnotationTransactionAttributeSource()));service=(CoursePrivateLegacySyncService)proxy.getProxy();}
    @AfterEach void clear(){f.clear();}
    Long contractId(){return f.source().getContractId();}
    @Test void changedLegacyPriceAppendsSnapshotWithoutChangingOldCoreOrMoney(){f.f.f.f.jdbc.update("UPDATE course_private_contract SET fixed_price=6.20,version=version+1 WHERE id=?",contractId());service.sync(contractId(),8L,"旧入口明确调整密价");var current=f.f.f.terms.selectById(f.f.f.f.contracts.selectById(contractId()).getCurrentTermId());assertNotEquals(f.sourceId,current.getId());assertEquals("6.20",current.getEffectiveFixedPrice().toPlainString());assertEquals("7.20",f.source().getEffectiveFixedPrice().toPlainString());assertEquals("SUPERSEDED",f.source().getStatus());assertEquals("LEGACY_UNKNOWN",current.getQualificationKind());assertNull(current.getQualificationBasisAmount());assertEquals(f.source().getEndAt(),current.getEndAt());f.f.f.f.money("100",f.f.f.wallet().getBalance());assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_reserved_wallet WHERE contract_id=?",Integer.class,contractId()));assertNotNull(f.f.f.events.selectByBizNo("legacy_sync_"+contractId()+"_"+f.f.f.f.contracts.selectById(contractId()).getVersion()));}
    @Test void sameSnapshotIsIdempotentAndDoesNotInventTime(){service.sync(contractId(),8L,"核对原兼容记录");service.sync(contractId(),8L,"重复核对");assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));}
    @Test void legacyStatusChangesDoNotRestoreTerminatedRelationship(){f.f.f.f.jdbc.update("UPDATE course_private_contract SET status='TERMINATED',version=version+1 WHERE id=?",contractId());service.sync(contractId(),8L,"终止旧协议");var current=f.f.f.terms.selectById(f.f.f.f.contracts.selectById(contractId()).getCurrentTermId());assertEquals("TERMINATED",current.getStatus());assertEquals("7.20",f.source().getEffectiveFixedPrice().toPlainString());}
    @Test void auditFailureRollsBackOriginalLegacyUpdateWhenCalledInItsTransaction(){f.f.f.f.jdbc.execute("ALTER TABLE course_private_term_event ADD CONSTRAINT reject_legacy_sync CHECK(event_type<>'LEGACY_CONFIG_SYNCED')");assertThrows(RuntimeException.class,()->f.f.f.f.tx.executeWithoutResult(tx->{f.f.f.f.jdbc.update("UPDATE course_private_contract SET fixed_price=6.20,version=version+1 WHERE id=?",contractId());service.sync(contractId(),8L,"失败原子回滚");}));assertEquals("7.20",f.f.f.f.contracts.selectById(contractId()).getFixedPrice().toPlainString());assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));}
    @Test void disabledSyncDoesNotReadOrCreateNewStructure(){org.springframework.test.util.ReflectionTestUtils.setField(service,"enabled",false);service.sync(-1L,8L,"灰度关闭");assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM course_private_contract_term",Integer.class));}
    @Test void originalWalletActivationPublishesSameTransactionProjection(){org.springframework.test.util.ReflectionTestUtils.setField(f.f.f.f.service,"legacySync",service);f.f.f.f.jdbc.update("UPDATE course_private_contract SET status='PENDING_ACTIVATION',activated_at=NULL WHERE id=?",contractId());f.f.f.f.jdbc.update("UPDATE course_private_contract_term SET status='PENDING_ACTIVATION',activated_at=NULL WHERE id=?",f.sourceId);f.f.f.f.jdbc.update("UPDATE course_reserved_wallet SET balance=0 WHERE contract_id=?",contractId());f.f.f.deposit("100","legacy_new_activation");var contract=f.f.f.f.contracts.selectById(contractId());var current=f.f.f.terms.selectById(contract.getCurrentTermId());assertEquals(contract.getActivatedAt(),current.getActivatedAt());assertEquals("ACTIVE",current.getStatus());assertNull(current.getQualificationBasisAmount());f.f.f.f.money("100",f.f.f.wallet().getBalance());}
    @Test void modernRelationshipCannotUseLegacyProjection(){f.f.f.f.jdbc.update("UPDATE course_private_contract SET operations_mode='PERFORMANCE_RENEWAL'");assertThrows(BusinessException.class,()->service.sync(contractId(),8L,"拒绝现代替换"));}
}
